test('addLine and removeLine work together', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;

  const addResult1 = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });
  assert(addResult1.ok === true);
  invoice = addResult1.value;

  const addResult2 = addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });
  assert(addResult2.ok === true);
  invoice = addResult2.value;

  assert.equal(invoice.lines.length, 3);

  const removeResult = removeLine(invoice, 'DES-HOUR');
  assert(removeResult.ok === true);
  invoice = removeResult.value;

  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

test('addLine to the same SKU multiple times accumulates qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;

  let addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert(addResult.ok === true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 8);

  addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert(addResult.ok === true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 10);
});

input.old_string:
/**
 * Calculate the next invoice number for a given issue date.
 * Format: INV-<year>-<counter> where counter is 4 digits, zero-padded, starting at 0001.
 * @param {Array<string>} existingNumbers - Array of invoice numbers already used, in any order
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.slice(0, 4);
  const prefix = `INV-${year}-`;

  const currentYearNumbers = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => Number(num.slice(prefix.length)))
    .filter((counter) => Number.isInteger(counter) && counter > 0);

  const maxCounter = currentYearNumbers.length > 0 ? Math.max(...currentYearNumbers) : 0;
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}

